package com.estateflow.service;
import com.estateflow.config.UserPreferences;import com.estateflow.dto.*;import com.estateflow.exception.ValidationException;import com.estateflow.model.*;import com.estateflow.model.enums.MaintenancePriority;import com.estateflow.security.*;import java.time.Clock;import java.time.LocalDate;import java.util.*;
/** Generates current in-app reminders from existing records; nothing is sent or marked as delivered. */
public final class NotificationService{
 private final RentReminderService rent;private final LeaseRenewalService leases;private final WorkOrderService workOrders;private final UserPreferences preferences;private final Clock clock;private final int leaseWindowDays;private final Authorizer auth;
 public NotificationService(RentReminderService rent,LeaseRenewalService leases,WorkOrderService workOrders,UserPreferences preferences,Clock clock,int leaseWindowDays,Authorizer auth){this.rent=rent;this.leases=leases;this.workOrders=workOrders;this.preferences=preferences;this.clock=clock;this.leaseWindowDays=leaseWindowDays;this.auth=auth;}
 public List<GeneratedNotification> generate()throws ValidationException{auth.require(Permission.VIEW_DATA);LocalDate today=LocalDate.now(clock);Map<String,GeneratedNotification> rows=new LinkedHashMap<>();if(preferences.rentReminders())for(RentReminderRow r:rent.reminders()){NotificationSeverity level=r.category()==RentReminderRow.Category.OVERDUE?NotificationSeverity.HIGH:r.category()==RentReminderRow.Category.DUE_TODAY?NotificationSeverity.ATTENTION:NotificationSeverity.UPCOMING;String label=switch(r.category()){case OVERDUE->"Overdue rent";case DUE_TODAY->"Rent due today";case UPCOMING->"Upcoming rent";};put(rows,new GeneratedNotification("RENT:"+r.chargeId(),NotificationType.RENT,level,label,r.propertyName(),r.tenantName()+" · Charge #"+r.chargeId(),r.dueDate(),r.agreementId(),r.balance(),"Generated"));}
  if(preferences.leaseReminders())for(ExpiringLeaseRow l:leases.endingWithinWarningWindow(leaseWindowDays)){put(rows,new GeneratedNotification("LEASE:"+l.agreementId(),NotificationType.LEASE,l.daysRemaining()<=7?NotificationSeverity.ATTENTION:NotificationSeverity.UPCOMING,"Lease ending",l.propertyName(),l.tenantName()+" · Agreement #"+l.agreementId()+" · "+l.daysRemaining()+" days remaining",l.effectiveEndDate(),l.agreementId(),l.monthlyRent(),"Generated"));}
  if(preferences.workOrderReminders()&&workOrders.isAvailable())for(WorkOrderRow w:workOrders.search(null,null,null,null,null,null,true)){if(w.dueDate()==null||!w.dueDate().isBefore(today))continue;put(rows,new GeneratedNotification("WORK_ORDER:"+w.id(),NotificationType.WORK_ORDER,NotificationSeverity.HIGH,"Work order overdue",w.propertyName(),w.title()+" · "+w.status().name().replace('_',' '),w.dueDate(),w.id(),w.actualCost(),"Generated"));}
  return rows.values().stream().sorted(Comparator.comparing(GeneratedNotification::severity).thenComparing(GeneratedNotification::dueDate,Comparator.nullsLast(Comparator.naturalOrder())).thenComparing(GeneratedNotification::key)).toList();
 }
 private static void put(Map<String,GeneratedNotification> rows,GeneratedNotification row){rows.putIfAbsent(row.key(),row);}
}
